try {
    let parsed;

    // Already a JSON object (from Inject node)
    if (typeof msg.payload === 'object' && msg.payload !== null) {
        parsed = msg.payload;
    }
    // JSON string format: {"product_name":"Widget","product_count":10,"weight":1.5}
    else if (typeof msg.payload === 'string' && msg.payload.startsWith('{')) {
        parsed = JSON.parse(msg.payload);
    }
    // CSV format: Widget,10,1.5
    else if (typeof msg.payload === 'string' && msg.payload.includes(',')) {
        const parts = msg.payload.split(',');
        parsed = {
            product_name: parts[0].trim(),
            product_count: parseInt(parts[1]),
            weight: parseFloat(parts[2])
        };
    }
    // Buffer
    else if (Buffer.isBuffer(msg.payload)) {
        parsed = {
            product_name: 'unknown',
            product_count: msg.payload.readUInt16BE(0),
            weight: msg.payload.readFloatBE(2)
        };
    }
    else {
        node.error('Unrecognized format: ' + typeof msg.payload, msg);
        return null;
    }

    msg.payload = parsed;
    return msg;

} catch (e) {
    node.error('Parse error: ' + e.message, msg);
    return null;
}

const data = msg.payload;

// Pass query directly via msg.query — skips Mustache template
msg.query = "INSERT INTO sensor_data (product_name, product_count, weight) VALUES ('" + data.product_name + "', " + data.product_count + ", " + data.weight + ");";

return msg;

// Get current count from flow context, start at 1
let count = flow.get('product_count') || 0;
count = count + 1;
flow.set('product_count', count);

// Fixed product name, sequential count, random weight between 0.5 and 10.0
msg.payload = {
    product_name: 'Widget_A',
    product_count: count,
    weight: Math.round((Math.random() * 9.5 + 0.5) * 100) / 100
};

return msg;
